import{_ as s,c as n,o as e,ag as i}from"./chunks/framework.FgzfQ7Ey.js";const u=JSON.parse('{"title":"Promise 与 async/await（Promise & async/await）","description":"","frontmatter":{},"headers":[],"relativePath":"js/promise-async.md","filePath":"js/promise-async.md","lastUpdated":1764505738000}'),l={name:"js/promise-async.md"};function t(o,a,r,c,p,d){return e(),n("div",null,[...a[0]||(a[0]=[i(`<h1 id="promise-与-async-await-promise-async-await" tabindex="-1">Promise 与 async/await（Promise &amp; async/await） <a class="header-anchor" href="#promise-与-async-await-promise-async-await" aria-label="Permalink to &quot;Promise 与 async/await（Promise &amp; async/await）&quot;">​</a></h1><h2 id="_1-概念定义" tabindex="-1">1. 概念定义 <a class="header-anchor" href="#_1-概念定义" aria-label="Permalink to &quot;1. 概念定义&quot;">​</a></h2><ul><li><strong>Promise</strong>：表示一个异步操作的最终完成或失败及其结果的对象。</li><li><strong>async/await</strong>：基于 Promise 的语法糖，用同步风格编写异步代码，提升可读性。</li></ul><h2 id="_2-产生原因-工作原理" tabindex="-1">2. 产生原因 / 工作原理 <a class="header-anchor" href="#_2-产生原因-工作原理" aria-label="Permalink to &quot;2. 产生原因 / 工作原理&quot;">​</a></h2><ul><li><strong>产生原因</strong>： <ul><li>异步操作中回调函数过多容易产生“回调地狱”；</li><li>需要统一管理异步状态和错误处理。</li></ul></li><li><strong>工作原理</strong>： <ul><li><strong>Promise 状态</strong>：pending（等待）、fulfilled（成功）、rejected（失败）。</li><li><strong>链式调用</strong>：<code>then</code>、<code>catch</code> 返回新的 Promise，支持链式处理。</li><li><strong>async/await</strong>：<code>async</code> 函数返回 Promise，<code>await</code> 暂停执行直到 Promise 完成，自动处理 resolved 值或 reject 异常。</li><li><strong>事件循环</strong>：Promise.then/await 等操作放入微任务队列，微任务优先于宏任务执行。</li></ul></li></ul><h2 id="_3-典型示例" tabindex="-1">3. 典型示例 <a class="header-anchor" href="#_3-典型示例" aria-label="Permalink to &quot;3. 典型示例&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>// Promise 示例</span></span>
<span class="line"><span>function fetchData() {</span></span>
<span class="line"><span>  return new Promise((resolve, reject) =&gt; {</span></span>
<span class="line"><span>    setTimeout(() =&gt; resolve(&#39;Data loaded&#39;), 1000);</span></span>
<span class="line"><span>  });</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span></span></span>
<span class="line"><span>fetchData()</span></span>
<span class="line"><span>  .then(data =&gt; console.log(data))</span></span>
<span class="line"><span>  .catch(err =&gt; console.error(err));</span></span>
<span class="line"><span></span></span>
<span class="line"><span>// async/await 示例</span></span>
<span class="line"><span>async function loadData() {</span></span>
<span class="line"><span>  try {</span></span>
<span class="line"><span>    const data = await fetchData();</span></span>
<span class="line"><span>    console.log(data);</span></span>
<span class="line"><span>  } catch (err) {</span></span>
<span class="line"><span>    console.error(err);</span></span>
<span class="line"><span>  }</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>loadData();</span></span></code></pre></div><ul><li><strong>解释</strong>：Promise 提供链式调用管理异步操作，async/await 提供更直观的同步风格写法，同时利用微任务队列保证事件循环顺序。</li></ul><h2 id="_4-应用场景" tabindex="-1">4. 应用场景 <a class="header-anchor" href="#_4-应用场景" aria-label="Permalink to &quot;4. 应用场景&quot;">​</a></h2><ul><li><strong>网络请求</strong>：fetch 或 Ajax 请求结果处理。</li><li><strong>定时任务</strong>：需要异步顺序执行的操作。</li><li><strong>异步流程控制</strong>：复杂异步逻辑中保证顺序、错误捕获和状态管理。</li><li><strong>前端数据流</strong>：异步加载组件或数据渲染。</li></ul><h2 id="_5-常见考点与陷阱" tabindex="-1">5. 常见考点与陷阱 <a class="header-anchor" href="#_5-常见考点与陷阱" aria-label="Permalink to &quot;5. 常见考点与陷阱&quot;">​</a></h2><ul><li><strong>链式调用错误处理</strong>：每个 then/catch 返回新的 Promise，需要正确捕获异常。</li><li><strong>async 函数返回值</strong>：始终返回 Promise，忘记处理可能导致意外行为。</li><li><strong>并发与顺序</strong>： <ul><li>并发执行使用 <code>Promise.all</code>；</li><li>顺序执行使用 <code>await</code> 或链式 then。</li></ul></li><li><strong>微任务优先级</strong>：Promise.then/await 是微任务，比 setTimeout 更早执行。</li></ul><h2 id="_6-优缺点总结" tabindex="-1">6. 优缺点总结 <a class="header-anchor" href="#_6-优缺点总结" aria-label="Permalink to &quot;6. 优缺点总结&quot;">​</a></h2><ul><li><strong>优点</strong>： <ul><li>避免回调地狱，异步逻辑可读性高；</li><li>错误处理统一，可用 try/catch；</li><li>支持顺序和并发控制。</li></ul></li><li><strong>缺点</strong>： <ul><li>async/await 会阻塞当前 async 函数的执行（非主线程阻塞，但会暂停该函数上下文）；</li><li>不合理的 await 可能降低并发效率；</li><li>对初学者需要理解事件循环与微任务。</li></ul></li></ul><h2 id="_7-一句话总结" tabindex="-1">7. 一句话总结 <a class="header-anchor" href="#_7-一句话总结" aria-label="Permalink to &quot;7. 一句话总结&quot;">​</a></h2><ul><li>Promise 与 async/await 是现代 JavaScript 异步编程核心工具，提供链式管理和同步风格写法，提高代码可读性与可维护性。</li></ul>`,16)])])}const g=s(l,[["render",t]]);export{u as __pageData,g as default};
